<span class="line"><span style="color:#C678DD;">        elif</span><span style="color:#ABB2BF;"> query_type </span><span style="color:#56B6C2;">==</span><span style="color:#98C379;"> &quot;balanced&quot;</span><span style="color:#ABB2BF;">:</span></span>
